class Solution:
    def passCode(self, grid: List[List[int]]) -> int:
        n = len(grid); MOD = 10**9 + 7
        comp = [[-1] * n for _ in range(n)]; c = 0
        for i in range(n):
            for j in range(n):
                if grid[i][j] != -1 and comp[i][j] == -1:
                    comp[i][j] = c; st = [(i, j)]
                    while st:
                        x, y = st.pop()
                        for a, b in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                            if 0 <= a < n and 0 <= b < n and grid[a][b] != -1 and comp[a][b] == -1:
                                comp[a][b] = c; st.append((a, b))
                    c += 1
        cells = [(grid[i][j], comp[i][j]) for i in range(n) for j in range(n) if grid[i][j] != -1]
        total = -(n * n - len(cells))
        if not cells: return total % MOD
        mx = max(v for v, _ in cells); where = [-1] * (mx + 1)
        for v, k in cells: where[v] = k
        for v, k in cells:                      # harmonic sum: about mx * ln(mx) steps
            for mult in range(2 * v, mx + 1, v):
                w = where[mult]
                if w != -1 and w != k: total += mult
        return total % MOD

