class Solution {
public:
    int passCode(vector<vector<int>>& g) {
        int n = g.size(); const long long MOD = 1000000007;
        vector<vector<int>> comp(n, vector<int>(n, -1)); int c = 0;
        for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) {
            if (g[i][j] == -1 || comp[i][j] != -1) continue;
            vector<pair<int,int>> st{{i, j}}; comp[i][j] = c;
            while (!st.empty()) {
                auto [x, y] = st.back(); st.pop_back();
                int dx[] = {1, -1, 0, 0}, dy[] = {0, 0, 1, -1};
                for (int d = 0; d < 4; d++) {
                    int a = x + dx[d], b = y + dy[d];
                    if (a >= 0 && b >= 0 && a < n && b < n && g[a][b] != -1 && comp[a][b] == -1) { comp[a][b] = c; st.push_back({a, b}); }
                }
            }
            c++;
        }
        long long total = 0; int mx = 0; vector<pair<int,int>> cells;
        for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) {
            if (g[i][j] == -1) total -= 1; else { cells.push_back({g[i][j], comp[i][j]}); mx = max(mx, g[i][j]); }
        }
        vector<int> where(mx + 1, -1);
        for (auto [v, k] : cells) where[v] = k;
        for (auto [v, k] : cells)
            for (long long m = 2LL * v; m <= mx; m += v)
                if (where[m] != -1 && where[m] != k) total += m;
        return (int)(((total % MOD) + MOD) % MOD);
    }
};

